77	@RestController
78	@CrossOrigin(exposedHeaders = "errors, content-type")
79	@RequestMapping("/api")
80	public class OwnerRestControllerV1 implements OwnersApi {
81	
82	    /** Maximum number of owners a single city may contain; creating an owner in a city that
83	     *  already has this many owners is rejected with 409 Conflict. */
84	    private static final int MAX_OWNERS_PER_CITY = 50;
85	
86	    /** When the owner's city already contains at least this many owners (but fewer than
87	     *  {@link #MAX_OWNERS_PER_CITY}, so the create is still allowed), the new owner's
88	     *  'capacityWarning' flag is set true to signal the city is approaching its capacity limit;
89	     *  otherwise it is false. */
90	    private static final int CAPACITY_WARNING_THRESHOLD = 40;
91	
92	    /** Maximum number of owners that may be created on a single day (by registration date); creating
93	     *  an owner once this many owners already carry today's registration date is rejected with
94	     *  429 Too Many Requests. */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /** When more than this many owners already carry today's registration date at creation time, the
98	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
99	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
100	
101	    /** Disposable email domains that are not accepted for an owner; a create whose email domain is on
102	     *  this blocklist is rejected with 400 Bad Request. Compared case-insensitively (lower-cased). */
103	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
104	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
105	
106	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
107	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
108	
109	    /** Dedicated notification logger; a welcome notification is enqueued here for each successful
110	     *  owner create, carrying the owner id and member id. */
111	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
112	
113	    /** Serializes the immutable structured audit event emitted alongside the audit line. */
114	    private static final ObjectMapper AUDIT_EVENT_MAPPER = JsonMapper.builder().build();
115	
116	    /** Monotonically increasing sequence stamped on each structured {@code OWNER_CREATED} event,
117	     *  shared across all creates so the events carry a strict global order. */
118	    private static final AtomicLong OWNER_CREATED_SEQUENCE = new AtomicLong();
119	
120	    private final ClinicService clinicService;
121	
122	    private final OwnerMapper ownerMapper;
123	
124	    private final PetMapper petMapper;
125	
126	    private final VisitMapper visitMapper;
127	
128	    private final TelephoneNormalizer telephoneNormalizer;
129	
130	    private final HouseholdNormalizer householdNormalizer;
131	
132	    private final AddressNormalizer addressNormalizer;
133	
134	    private final EmailNormalizer emailNormalizer;
135	
136	    /**
137	     * Records the owner created for each already-seen {@code Idempotency-Key}, so a create that
138	     * repeats with the same key returns the originally created owner (200) instead of creating a
139	     * duplicate. Keyed by the header value; concurrent because creates may be handled on any thread.
140	     */
141	    private final java.util.concurrent.ConcurrentMap<String, OwnerDto> idempotentCreates =
142	        new java.util.concurrent.ConcurrentHashMap<>();
143	
144	    public OwnerRestControllerV1(ClinicService clinicService,
145	                                 OwnerMapper ownerMapper,
146	                                 PetMapper petMapper,
147	                                 VisitMapper visitMapper,
148	                                 TelephoneNormalizer telephoneNormalizer,
149	                                 HouseholdNormalizer householdNormalizer,
150	                                 AddressNormalizer addressNormalizer,
151	                                 EmailNormalizer emailNormalizer) {
152	        this.clinicService = clinicService;
153	        this.ownerMapper = ownerMapper;
154	        this.petMapper = petMapper;
155	        this.visitMapper = visitMapper;
156	        this.telephoneNormalizer = telephoneNormalizer;
157	        this.householdNormalizer = householdNormalizer;
158	        this.addressNormalizer = addressNormalizer;
159	        this.emailNormalizer = emailNormalizer;
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
165	        Collection<Owner> owners;
166	        if (lastName != null) {
167	            owners = this.clinicService.findOwnerByLastName(lastName);
168	        } else {
169	            owners = this.clinicService.findAllOwners();
170	        }
171	        if (owners.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
190	        // Idempotent create: when the request carries an 'Idempotency-Key' header that has already
191	        // been used for a successful create, return the originally created owner with 200 OK instead
192	        // of running the create pipeline again (which would otherwise reject the repeat as a duplicate
193	        // with 409). A first, unseen key runs the normal create and records its result under the key.
194	        String idempotencyKey = currentIdempotencyKey();
195	        if (idempotencyKey == null || idempotencyKey.isBlank()) {
196	            return createOwner(ownerFieldsDto);
197	        }
198	        OwnerDto previouslyCreated = idempotentCreates.get(idempotencyKey);
199	        if (previouslyCreated != null) {
200	            return new ResponseEntity<>(previouslyCreated, HttpStatus.OK);
201	        }
202	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
203	        idempotentCreates.put(idempotencyKey, response.getBody());
204	        return response;
205	    }
206	
207	    /**
208	     * Returns the value of the current request's {@code Idempotency-Key} header, or {@code null} when
209	     * the request carries no such header (or there is no active servlet request). Reading it from the
210	     * request context here keeps the header — a request-level concern surrounding the create — out of
211	     * the generated {@link #addOwner} signature and the {@link #createOwner} pipeline.
212	     *
213	     * @return the {@code Idempotency-Key} header value, or {@code null} when absent
214	     */
215	    private String currentIdempotencyKey() {
216	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
217	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
218	            return servletAttributes.getRequest().getHeader("Idempotency-Key");
219	        }
220	        return null;
221	    }
222	
223	    /**
224	     * Runs the full owner-creation pipeline for a create request and returns the 201 Created
225	     * response for the newly persisted owner: the request fields are mapped and normalized, every
226	     * create-time policy (per-day and per-city quota, household membership, identity duplicate and
227	     * soft-duplicate) is applied in order, the create-time derived fields are assigned, the owner is
228	     * saved and audited, and a {@code Location} header for the new owner is set. Keeping the pipeline
229	     * in its own method leaves {@link #addOwner} as the thin request entry point, so request-level
230	     * concerns that merely surround a create (rather than being one of its steps) can be layered in
231	     * {@code addOwner} without disturbing the creation steps gathered here.
232	     *
233	     * @param ownerFieldsDto the submitted owner fields
234	     * @return a 201 Created response carrying the persisted owner and its {@code Location} header
235	     */
236	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
237	        HttpHeaders headers = new HttpHeaders();
238	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
239	        normalizeOwnerFields(owner);
240	        // Enforce the pre-persistence policies that can reject the new owner outright.
241	        rejectDisallowedOwnerCreation(owner);
242	        // Resolve the owner's household membership: assign the deterministic 'householdId' (a pure
243	        // function of last name and postcode), cap the membership level for a new household member,
244	        // and record the household size. The household id is no longer part of the identity key, so
245	        // this no longer rejects a household duplicate: owners sharing a household are distinguished
246	        // by the identity-key check below and otherwise flagged as soft duplicates.
247	        boolean declaredHouseholdMember =
248	            applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
249	        // Reject the create when the owner's whole derived identity key (the SHA-256 over normalized
250	        // telephone, lower-cased email and the Soundex of the last name) already matches an existing
251	        // owner. This single rule subsumes the former separate telephone, email and household
252	        // duplicate checks.
253	        rejectWhenIdentityInUse(owner);
254	        // Flag the owner as a possible (soft) duplicate when, although not a hard duplicate, it
255	        // shares an existing owner's last name and postcode with a different telephone. A declared
256	        // household member is never flagged: it is a known member, not a suspected duplicate.
257	        assignPossibleDuplicate(owner, declaredHouseholdMember);
258	        // Assign the remaining create-time derived fields (namesake count, member id
259	        // and bulk-signup warning), each fixed at creation time.
260	        assignDerivedFields(owner);
261	        // Assign the (household-capped) membership level, fixed at creation time. This runs after the
262	        // derived fields above because the level is computed from the membership points, which depend
263	        // on the namesake count assigned in assignDerivedFields.
264	        assignMembershipLevel(owner);
265	        this.clinicService.saveOwner(owner);
266	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
267	        // Record the successful create on the dedicated AUDIT log.
268	        auditOwnerCreated(owner, ownerDto);
269	        // Enqueue the welcome notification for the newly created owner.
270	        enqueueWelcomeNotification(owner);
271	        headers.setLocation(UriComponentsBuilder.newInstance()
272	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
273	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
274	    }
275	
276	    /**
277	     * Enqueues the welcome notification for a newly created owner by emitting a line on the
278	     * dedicated {@code NOTIFY} log carrying the owner id and its member id, so the welcome side-effect
279	     * of a create has a single home separate from the audit trail. The member id is resolved through
280	     * {@link #primaryIdentifier} so the notification follows the owner's primary identifier.
281	     *
282	     * @param owner the persisted owner to welcome
283	     */
284	    private void enqueueWelcomeNotification(Owner owner) {
285	        NOTIFY.info("Welcome notification: ownerId={} memberId={}",
286	            owner.getId(), primaryIdentifier(owner));
287	    }
288	
289	    /**
290	     * Emits the audit line recording a successful owner create on the dedicated {@code AUDIT} log,
291	     * carrying the owner id, its current primary identifier (see {@link #primaryIdentifier}), the
292	     * registration date and membership level so the create can be traced. Keeping
293	     * the audit emission in its own helper leaves {@link #createOwner} a thin pipeline and gives the
294	     * create's audit side-effects a single home, so a further audit side-effect of a create is added
295	     * here (or as a sibling helper) rather than inline in the pipeline.
296	     *
297	     * @param owner    the persisted owner
298	     * @param ownerDto the mapped view of the persisted owner, source of the membership fields
299	     */
300	    private void auditOwnerCreated(Owner owner, OwnerDto ownerDto) {
301	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
302	            owner.getId(), primaryIdentifier(owner), owner.getRegistrationDate(),
303	            ownerDto.getMembershipLevel());
304	        auditOwnerCreatedEvent(owner, ownerDto);
305	    }
306	
307	    /**
308	     * The schema version stamped on every structured {@code OWNER_CREATED} audit event. Version 2
309	     * groups the identity under the owner's version-2 identifiers: it carries an explicit
310	     * {@code schemaVersion} of 2 and the owner segment recomputed from the version-2 identity.
311	     */
312	    private static final int AUDIT_EVENT_SCHEMA_VERSION = 2;
313	
314	    /**
315	     * Emits the immutable structured {@code OWNER_CREATED} event on the {@code AUDIT} log as a JSON
316	     * object {@code {seq, schemaVersion, ownerId, memberId, membershipLevel, ownerSegment, event}}.
317	     * The {@code seq} is a strictly increasing integer across every create (see
318	     * {@link #OWNER_CREATED_SEQUENCE}), giving the events a total order, and {@code schemaVersion} is
319	     * the fixed schema version of the event (see {@link #AUDIT_EVENT_SCHEMA_VERSION}). The identifier
320	     * field carries the owner's current primary identifier (see {@link #primaryIdentifier}) — the
321	     * version-2 member id — and {@code ownerSegment} the marketing segment recomputed from the
322	     * version-2 identity, so every audit consumer follows the primary identifier by changing only
323	     * {@link #primaryIdentifier}.
324	     *
325	     * @param owner    the persisted owner
326	     * @param ownerDto the mapped view of the persisted owner, source of the membership level and
327	     *                 owner segment
328	     */
329	    private void auditOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
330	        OwnerCreatedEvent event = new OwnerCreatedEvent(
331	            OWNER_CREATED_SEQUENCE.incrementAndGet(), AUDIT_EVENT_SCHEMA_VERSION, owner.getId(),
332	            primaryIdentifier(owner), ownerDto.getMembershipLevel(),
333	            ownerDto.getOwnerSegment() == null ? null : ownerDto.getOwnerSegment().getValue(),
334	            "OWNER_CREATED");
335	        AUDIT.info(AUDIT_EVENT_MAPPER.writeValueAsString(event));
336	    }
337	
338	    /**
339	     * The immutable structured audit event published for a successful owner create. It carries an
340	     * explicit {@code schemaVersion} (2), its {@code memberId} field carries the owner's current
341	     * primary identifier (see {@link #primaryIdentifier}), and {@code ownerSegment} the marketing
342	     * segment recomputed from the version-2 identity, so the same event shape follows the identifier
343	     * as it changes.
344	     */
345	    private record OwnerCreatedEvent(long seq, int schemaVersion, Integer ownerId, String memberId,
346	        Integer membershipLevel, String ownerSegment, String event) {
347	    }
348	
349	    /**
350	     * Returns the owner's current primary identifier: the single value that identifies the owner in
351	     * the audit trail and in any audit side-effect of a create. This is the member id; resolving it
352	     * through one accessor means that if the primary identifier is later changed every audit consumer
353	     * follows the new identifier by changing only this method.
354	     *
355	     * @param owner the owner whose primary identifier is required
356	     * @return the owner's current primary identifier
357	     */
358	    private String primaryIdentifier(Owner owner) {
359	        return owner.getMemberId();
360	    }
361	
362	    /**
363	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
364	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
365	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
366	     * the sequence of create-time rejections stays readable and a new rule is added as one more
367	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
368	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
369	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}.
370	     *
371	     * @param owner the newly mapped and normalized owner being created
372	     */
373	    private void rejectDisallowedOwnerCreation(Owner owner) {
374	        rejectWhenDailyLimitReached(owner);
375	        rejectWhenCityAtCapacity(owner);
376	    }
377	
378	    /**
379	     * Applies the household-membership rules for a newly normalized owner being created. The
380	     * household id is a deterministic function of the owner's last name and postcode, so owners
381	     * with the same last name and postcode share it automatically; it is assigned to the new owner
382	     * here. Because the household is keyed on (last name, postcode), any existing owner with the
383	     * same last name and postcode is a member of the same household. A new owner may join an
384	     * existing household: rather than the create being rejected, the newcomer's membership level is
385	     * capped at one above the household's current maximum (see {@link #assignMembershipLevel}). When
386	     * the request declares it shares the household via {@code sharesHousehold} the owner is a known,
387	     * declared member and is never flagged as a possible duplicate. The owner's
388	     * {@code householdSize} (the number of owners sharing the household after this create) is
389	     * recorded either way.
390	     *
391	     * @param owner           the newly mapped and normalized owner being created
392	     * @param sharesHousehold whether the request declared that the owner shares an existing household
393	     * @return {@code true} if the owner joined an existing household as a declared member
394	     */
395	    private boolean applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
396	        // Assign the deterministic household id (a pure function of last name and postcode) so every
397	        // owner with the same last name and postcode shares it automatically.
398	        owner.setHouseholdId(householdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
399	        // Identify any existing owners in the same household (same computed household id). A new owner
400	        // may join an existing household: its membership level is capped at one above the household's
401	        // current maximum (see assignMembershipLevel) rather than the create being rejected outright.
402	        List<Owner> householdMembers = sameHouseholdOwners(owner);
403	        // An owner that joins an existing household while the request declares it shares that
404	        // household is a known, declared member and so is never flagged as a possible duplicate.
405	        boolean declaredHouseholdMember = !householdMembers.isEmpty() && sharesHousehold;
406	        // Record the size of this owner's household after this create, fixed at creation time.
407	        owner.setHouseholdSize(householdMembers.size() + 1);
408	        return declaredHouseholdMember;
409	    }
410	
411	    /**
412	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
413	     * has already been resolved: the namesake count, the per-city member id, the bulk-signup warning
414	     * flag and the city capacity warning flag. Each value is fixed at creation time and is
415	     * independent of the others. Grouping them
416	     * here keeps {@link #addOwner} focused on the high-level create sequence.
417	     *
418	     * @param owner the owner being created, already normalized and with its household resolved
419	     */
420	    private void assignDerivedFields(Owner owner) {
421	        // Record how many existing owners already share this owner's first and last name
422	        // (compared case-insensitively) before this create, fixed at creation time.
423	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
424	        // Assign the member id '<REGION><FY><HASH8><CHK>' from the region derived from the postcode,
425	        // the 2-digit fiscal year of the registration date, an 8-hex-character hash of the normalized
426	        // telephone and last name, and a Luhn check digit over the preceding digits, fixed at
427	        // creation time.
428	        owner.setMemberId(memberId(owner));
429	        // Flag the create when more than 80 owners have already been created on this owner's
430	        // (adjusted business-day) registration date, fixed at creation time.
431	        owner.setBulkSignupWarning(
432	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
433	        // Flag the create when the owner's city is approaching its capacity limit: it already holds
434	        // between CAPACITY_WARNING_THRESHOLD and MAX_OWNERS_PER_CITY - 1 owners (40-49). A city at or
435	        // over the limit is rejected earlier (see rejectWhenCityAtCapacity), so this is never reached
436	        // for a full city. Fixed at creation time.
437	        int cityOwners = countOwnersInCity(owner.getCity());
438	        owner.setCapacityWarning(
439	            cityOwners >= CAPACITY_WARNING_THRESHOLD && cityOwners < MAX_OWNERS_PER_CITY);
440	    }
441	
442	    /**
443	     * Assigns the new owner's membership level, capped by their household, and fixes it at creation
444	     * time. The level a newly created owner would earn from their membership points cannot exceed
445	     * one above the current maximum membership level among their existing household members (the
446	     * owners already sharing this owner's household id); the capped value is stored so it is returned
447	     * unchanged on later reads. When the owner has no existing household member no cap applies and
448	     * the plain points-derived level is used.
449	     *
450	     * @param owner the owner being created, already normalized and with its derived fields assigned
451	     */
452	    private void assignMembershipLevel(Owner owner) {
453	        int level = ownerMapper.membershipLevel(ownerMapper.membershipPoints(owner));
454	        List<Owner> householdMembers = sameHouseholdOwners(owner);
455	        if (!householdMembers.isEmpty()) {
456	            int maxMemberLevel = householdMembers.stream()
457	                .mapToInt(this::memberLevel)
458	                .max()
459	                .getAsInt();
460	            level = Math.min(level, maxMemberLevel + 1);
461	        }
462	        owner.setMembershipLevel(level);
463	    }
464	
465	    /**
466	     * Returns an existing household member's membership level for the purpose of capping a new
467	     * member's level: the level stored on the member when present (the already-capped value fixed at
468	     * its own creation), otherwise the level derived from its membership points (for members created
469	     * before the level was persisted).
470	     *
471	     * @param member an existing owner in the same household
472	     * @return the member's membership level
473	     */
474	    private int memberLevel(Owner member) {
475	        return member.getMembershipLevel() != null
476	            ? member.getMembershipLevel()
477	            : ownerMapper.membershipLevel(ownerMapper.membershipPoints(member));
478	    }
479	
480	    /**
481	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
482	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) is the SHA-256 hex over
483	     * the normalized telephone, the lower-cased email (or empty) and the Soundex of the last name, so
484	     * this single rule replaces the former separate telephone, email and household duplicate checks:
485	     * two owners collide only when their whole keys are equal, and members of one household with
486	     * different telephones have different keys and are both allowed (instead flagged as soft
487	     * duplicates).
488	     *
489	     * @param owner the owner being created, already normalized
490	     */
491	    private void rejectWhenIdentityInUse(Owner owner) {
492	        String identityKey = owner.getIdentityKey();
493	        boolean inUse = existingOwners()
494	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
495	        if (inUse) {
496	            throw new DuplicateIdentityException(
497	                "An owner with identity key " + identityKey + " already exists");
498	        }
499	    }
