501	    /**
502	     * Assigns the soft-duplicate flags for a newly normalized owner that has already passed the hard
503	     * duplicate (identity-key) check. When an existing owner has a different identity key but shares
504	     * this owner's postcode and the Soundex code of its last name, the new owner is still created but
505	     * flagged as a possible duplicate: {@code possibleDuplicate} is set true and
506	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest such id when several match).
507	     * Otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is left absent.
508	     * A postcode is required on both sides for a match, so an owner without a postcode is never a
509	     * possible duplicate. A declared household member is never flagged: it is a known member of the
510	     * household, not a suspected duplicate. Both values are fixed at creation time.
511	     *
512	     * @param owner                   the owner being created, already normalized and confirmed not a
513	     *                                hard duplicate
514	     * @param declaredHouseholdMember whether the owner joined an existing household as a declared
515	     *                                member
516	     */
517	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
518	        Integer matchId = declaredHouseholdMember || owner.getPostcode() == null ? null : existingOwners()
519	            .filter(existing -> isPossibleDuplicateOf(existing, owner))
520	            .map(Owner::getId)
521	            .min(Integer::compareTo)
522	            .orElse(null);
523	        owner.setPossibleDuplicate(matchId != null);
524	        owner.setPossibleDuplicateOf(matchId);
525	    }
526	
527	    /**
528	     * Tests whether an existing owner makes the owner being created a possible (soft) duplicate: the
529	     * two have different identity keys (an equal key would already have been rejected as a hard
530	     * duplicate) but share a postcode (required on both sides, so an owner without a postcode never
531	     * matches) and the Soundex code of their last name. A match flags the new owner as a possible
532	     * duplicate of the existing one without rejecting the create.
533	     *
534	     * @param existing an existing owner to compare against
535	     * @param owner    the owner being created
536	     * @return {@code true} if the existing owner makes the new owner a possible duplicate
537	     */
538	    private boolean isPossibleDuplicateOf(Owner existing, Owner owner) {
539	        return existing.getPostcode() != null
540	            && existing.getPostcode().equals(owner.getPostcode())
541	            && Soundex.encode(existing.getLastName()).equals(Soundex.encode(owner.getLastName()))
542	            && !existing.getIdentityKey().equals(owner.getIdentityKey());
543	    }
