545	    /**
546	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
547	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
548	     *
549	     * @param owner the owner being created
550	     */
551	    private void rejectWhenDailyLimitReached(Owner owner) {
552	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
553	            throw new DailyOwnerLimitExceededException(
554	                "The maximum number of owners that may be created today has already been reached");
