571	    /**
572	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
573	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
574	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
575	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
576	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
577	     * server's current date. Canonicalising the address here, before the household checks read it,
578	     * ensures duplicate detection and the shared household id both compare the normalized form.
579	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
580	     * duplicate, household and member-id rules.
581	     *
582	     * @param owner the newly mapped owner to canonicalize
583	     */
584	    private void normalizeOwnerFields(Owner owner) {
585	        // Canonicalize the owner's address fields on create so the address is stored and returned in
586	        // canonical form and every later comparison (household duplicate detection and the shared
587	        // household id) uses it. A value that is blank after normalization is rejected with 400.
588	        normalizeAddressFields(owner);
589	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
590	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
591	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
592	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
593	        // Store the (already syntactically validated) email lower-cased so it is persisted and
594	        // returned in canonical form. A missing email is left untouched.
595	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
596	        // Reject an email whose domain is on the disposable-domain blocklist with 400, after
597	        // canonicalization so the comparison sees the lower-cased value.
598	        rejectDisposableEmailDomain(owner.getEmail());
599	        // Validate the optional postcode against the fixed range for the city's region. A postcode
600	        // is checked only when present (it is optional); one out of range for the city's region is
601	        // rejected with 400. A city with no known region accepts any 4-digit postcode. The stored
602	        // value is left unchanged.
603	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
604	        // Reject a supplied registration date that is later than the server's current date with
605	        // 400, before any defaulting or business-day adjustment, so a future date is never
606	        // persisted regardless of how the roll-forward would move it.
607	        rejectFutureRegistrationDate(owner.getRegistrationDate());
608	        // Default the registration date to the server's current date when the client did not
609	        // supply one, then roll the effective date forward to a business day so a Saturday or
610	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
611	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
612	        // date-derived field (such as the member id's fiscal-year segment) and the per-day
613	        // create-limit are computed from.
614	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
615	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
616	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
617	    }
618	
619	    /**
620	     * Canonicalizes a newly mapped owner's address on create, in place, so it is persisted and
621	     * returned in canonical form. The owner may supply its address in either of two forms and the
622	     * structured form is preferred when present: when a non-blank {@code addressLine1} is supplied it
623	     * (and the optional {@code addressLine2}) is normalized (trimmed, whitespace collapsed, upper-cased
624	     * and common street-type abbreviations expanded) via {@link AddressNormalizer}, otherwise the flat
625	     * {@code address} input is normalized for backward compatibility. Whichever form is supplied, the
626	     * stored {@code address} is composed from the normalized structured lines when present — the
627	     * normalized {@code addressLine1} with a single space and the normalized {@code addressLine2}
628	     * appended when an {@code addressLine2} is present — or the normalized flat address otherwise. An
629	     * owner that supplies no address in either form is rejected with 400. Canonicalising the address
630	     * here, before the household checks read it, ensures duplicate detection and the shared household
631	     * id both compare the normalized form. Isolating the address concern in its own helper keeps
632	     * {@link #normalizeOwnerFields} focused on sequencing the per-field canonicalizations.
633	     *
634	     * @param owner the newly mapped owner whose address is canonicalized
635	     */
636	    private void normalizeAddressFields(Owner owner) {
637	        if (owner.getAddressLine1() != null && !owner.getAddressLine1().isBlank()) {
638	            String line1 = addressNormalizer.normalize(owner.getAddressLine1());
639	            owner.setAddressLine1(line1);
640	            String composed = line1;
641	            if (owner.getAddressLine2() != null && !owner.getAddressLine2().isBlank()) {
642	                String line2 = addressNormalizer.normalize(owner.getAddressLine2());
643	                owner.setAddressLine2(line2);
644	                composed = line1 + " " + line2;
645	            }
646	            owner.setAddress(composed);
647	        }
648	        else {
649	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
650	        }
651	    }
652	
653	    /**
654	     * Rejects a supplied email whose domain is on the disposable-domain blocklist
655	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}) with a 400 Bad Request. The email is already canonicalized
656	     * (lower-cased) here, so the domain — the part after the final {@code '@'} — is compared directly
657	     * against the lower-cased blocklist. A {@code null} email (email is optional) or one without a
658	     * domain part is left untouched.
659	     *
660	     * @param email the owner's canonicalized email, or {@code null} when absent
661	     */
662	    private void rejectDisposableEmailDomain(String email) {
663	        if (email == null) {
664	            return;
665	        }
666	        int at = email.lastIndexOf('@');
667	        if (at < 0) {
668	            return;
669	        }
670	        String domain = email.substring(at + 1).toLowerCase(Locale.ROOT);
671	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
672	            throw new DisposableEmailException(
673	                "The supplied email domain " + domain + " is on the disposable-domain blocklist");
674	        }
675	    }
676	
677	    /**
678	     * Rejects a supplied registration date that is later than the server's current date with a
679	     * 400 Bad Request. A missing registration date (defaulted to the server date later) is
680	     * accepted, and a date on or before today is left for the normal defaulting and business-day
681	     * adjustment.
682	     *
683	     * @param registrationDate the client-supplied registration date, or {@code null} when absent
684	     */
685	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
686	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
687	            throw new InvalidRegistrationDateException(
688	                "The supplied registration date " + registrationDate + " is later than the current date");
689	        }
690	    }
