692	    /**
693	     * The fixed list of public holidays. A registration date that lands on one of these dates is
694	     * rolled forward to the next non-holiday business day, in addition to the weekend rule.
695	     */
696	    private static final java.util.Set<java.time.LocalDate> PUBLIC_HOLIDAYS = java.util.Set.of(
697	        java.time.LocalDate.of(2026, 1, 1),
698	        java.time.LocalDate.of(2026, 1, 26),
699	        java.time.LocalDate.of(2026, 4, 25),
700	        java.time.LocalDate.of(2026, 12, 25),
701	        java.time.LocalDate.of(2026, 12, 28));
702	
703	    /**
704	     * Rolls a registration date forward to a business day: a Saturday, Sunday or listed public
705	     * holiday advances to the next non-holiday weekday, while an ordinary weekday is returned
706	     * unchanged. Applied to the effective registration date (whether supplied in the request or
707	     * defaulted to the server date) so the persisted registration date, every value derived from it
708	     * and the per-day create-limit all use the adjusted business day.
709	     *
710	     * @param date the effective registration date
711	     * @return the same date if it is a non-holiday weekday, otherwise the next non-holiday business day
712	     */
713	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
714	        java.time.LocalDate adjusted = date;
715	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
716	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY
717	            || PUBLIC_HOLIDAYS.contains(adjusted)) {
718	            adjusted = adjusted.plusDays(1);
719	        }
720	        return adjusted;
721	    }
722	
723	    /**
724	     * Builds the member id '<REGION><FY><HASH8><CHK>' for a newly created owner, where REGION is the
725	     * region derived from the owner's postcode (falling back to the city, via
726	     * {@link LocalityResolver}), FY is the last two digits of the fiscal year of the
727	     * (business-day-adjusted) registration date, HASH8 is the first 8 upper-case hex characters of
728	     * the SHA-256 digest over the owner's normalized telephone concatenated with the last name, and
729	     * CHK is a single Luhn check digit over the decimal digits of '<REGION><FY><HASH8>' (e.g.
730	     * 'NSW26A1B2C3D45'). When that base id already belongs to an existing owner, '-<n>' is appended
731	     * with the smallest n of 2 or more that makes it unique, so distinct owners always receive
732	     * distinct member ids.
733	     *
734	     * @param owner the owner being created, already normalized
735	     * @return the formatted, de-duplicated member id
736	     */
737	    private String memberId(Owner owner) {
738	        String region = LocalityResolver.identityRegion(owner.getCity(), owner.getPostcode());
739	        String fy = String.format("%02d",
740	            org.springframework.samples.petclinic.util.FiscalYear.of(owner.getRegistrationDate()) % 100);
741	        String hash8 = Sha256Hex.upperHexPrefix(owner.getTelephone() + owner.getLastName(), 8);
742	        String base = MemberId.format(region, fy, hash8);
743	        return deduplicateCode(base, existingMemberIds());
744	    }
745	
746	    /**
747	     * Collects the member ids already assigned to existing owners, the set a newly built id is
748	     * de-duplicated against. Gathering them here keeps {@link #memberId} focused on building the
749	     * id and lets the uniqueness step (see {@link #deduplicateCode}) work against the ids alone.
750	     *
751	     * @return the member ids currently in use
752	     */
753	    private Set<String> existingMemberIds() {
754	        return existingOwners()
755	            .map(Owner::getMemberId)
756	            .filter(id -> id != null)
757	            .collect(Collectors.toSet());
758	    }
759	
760	    /**
761	     * Returns a unique code for a newly built base identifier: the base itself when it is not already
762	     * taken, otherwise the base with {@code "-<n>"} appended, using the smallest {@code n} of 2 or
763	     * more that makes it unique. Keeping the collision rule in its own helper leaves the identifier's
764	     * construction to its builder and gives the "make it unique" step a single home independent of
765	     * which identifier is being assigned.
766	     *
767	     * @param base  the freshly built identifier, before any uniqueness suffix
768	     * @param taken the identifiers already in use
769	     * @return {@code base} when unused, otherwise the smallest {@code base + "-" + n} not in {@code taken}
770	     */
771	    private String deduplicateCode(String base, Set<String> taken) {
772	        if (!taken.contains(base)) {
773	            return base;
774	        }
775	        int n = 2;
776	        while (taken.contains(base + "-" + n)) {
777	            n++;
778	        }
779	        return base + "-" + n;
780	    }
