782	    /**
783	     * Streams the existing owners that the create-time rules match a new owner against. Every
784	     * duplicate, quota and derived-field rule scans this same set of owners and differs only in the
785	     * predicate it applies, so fetching them is centralized here to keep each rule focused on its
786	     * own matching criterion rather than on how the existing owners are retrieved.
787	     *
788	     * @return a stream over all existing owners
789	     */
790	    private Stream<Owner> existingOwners() {
791	        // Exclude soft-deleted owners: a deleted owner is retained for reads but must not block a
792	        // new create, so the duplicate, identity and household checks (and the other create-time
793	        // scans built on this helper) ignore it.
794	        return this.clinicService.findAllOwners().stream()
795	            .filter(existing -> !Boolean.TRUE.equals(existing.getDeleted()));
796	    }
