798	    /**
799	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
800	     * enforce the per-city capacity limit and fix an owner's capacity-warning flag at creation time.
801	     *
802	     * @param city the city of the owner being created
803	     * @return the number of existing owners in a matching city
804	     */
805	    private int countOwnersInCity(String city) {
806	        return (int) existingOwners()
807	            .filter(existing -> existing.getCity() != null
808	                && existing.getCity().equalsIgnoreCase(city))
809	            .count();
810	    }
811	
812	    /**
813	     * Counts the existing owners whose registration date is the given adjusted business day. Used
814	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
815	     * owners already carry that business day as their registration date.
816	     *
817	     * @param date the adjusted business-day registration date to match
818	     * @return the number of existing owners registered on that date
819	     */
820	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
821	        return (int) existingOwners()
822	            .filter(existing -> date.equals(existing.getRegistrationDate()))
823	            .count();
824	    }
825	
826	    /**
827	     * Returns the existing owners in the given owner's household, i.e. those sharing its
828	     * deterministic household id (the same last name and postcode). The id is computed via
829	     * {@link HouseholdNormalizer} so that last names differing only in letter case or in incidental
830	     * whitespace are treated as the same household. Centralising how "the same household" is matched
831	     * here keeps that definition in one place for every caller.
832	     *
833	     * @param owner the owner being created, with its household id already assigned
834	     * @return the existing owners in the owner's household (possibly empty)
835	     */
836	    private List<Owner> sameHouseholdOwners(Owner owner) {
837	        String householdId = owner.getHouseholdId();
838	        return existingOwners()
839	            .filter(existing -> householdId.equals(
840	                householdNormalizer.householdId(existing.getLastName(), existing.getPostcode())))
841	            .toList();
842	    }
843	
844	    /**
845	     * Counts the existing owners who share the given first and last name, compared
846	     * case-insensitively. Used to fix an owner's namesake count at creation time.
847	     *
848	     * @param firstName the first name of the owner being created
849	     * @param lastName  the last name of the owner being created
850	     * @return the number of existing owners with a matching first and last name
851	     */
852	    private int countNamesakes(String firstName, String lastName) {
853	        return (int) existingOwners()
854	            .filter(existing -> existing.getFirstName() != null
855	                && existing.getFirstName().equalsIgnoreCase(firstName)
856	                && existing.getLastName() != null
857	                && existing.getLastName().equalsIgnoreCase(lastName))
858	            .count();
859	    }
