863	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
864	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
865	        if (currentOwner == null) {
866	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
867	        }
868	        currentOwner.setAddress(ownerFieldsDto.getAddress());
869	        currentOwner.setCity(ownerFieldsDto.getCity());
870	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
871	        currentOwner.setLastName(ownerFieldsDto.getLastName());
872	        // Normalize the telephone to canonical E.164 form so it is stored and returned
873	        // consistently with create; an unformattable value is rejected with 400.
874	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
875	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
876	        this.clinicService.saveOwner(currentOwner);
877	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
878	    }
