179	        return handleOwnerRuleException(e, "Invalid owner field", HttpStatus.BAD_REQUEST, request);
180	    }
181	
182	    /**
183	     * Shared handling for the {@link OwnerRuleException} hierarchy: logs the offending rule and
184	     * builds a {@link ProblemDetail} response at the status the rule maps to, using the exception's
185	     * own {@link OwnerRuleException#getDetail()} as the client-facing detail.
186	     *
187	     * @param e        the rule violation to report
188	     * @param logLabel the human-readable category prefix for the warning log line
189	     * @param status   the HTTP status this rule maps to
190	     * @param request  {@link HttpServletRequest} object referring to the current request.
191	     * @return A {@link ResponseEntity} containing the error information and the given status
192	     */
193	    private ResponseEntity<ProblemDetail> handleOwnerRuleException(OwnerRuleException e, String logLabel, HttpStatus status, HttpServletRequest request) {
194	        logger.warn("{} ({}) at {} {}: {}",
195	            logLabel,
196	            e.getClass().getSimpleName(),
197	            request.getMethod(),
198	            request.getRequestURI(),
199	            e.getMessage());
200	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getDetail());
201	        return ResponseEntity.status(status).body(detail);
202	    }
203	
204	    /**
205	     * Handles exception thrown by Bean Validation on controller methods parameters
206	     *
207	     * @param e The {@link MethodArgumentNotValidException} to be handled
208	     * @param request {@link HttpServletRequest} object referring to the current request.
209	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
210	     */
211	    @ExceptionHandler(MethodArgumentNotValidException.class)
212	    @ResponseBody
213	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
214	        HttpStatus status = HttpStatus.BAD_REQUEST;
215	        BindingErrorsResponse errors = new BindingErrorsResponse();
216	        BindingResult bindingResult = e.getBindingResult();
217	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
218	        if (bindingResult.hasErrors()) {
219	            errors.addAllErrors(bindingResult);
220	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
221	                .map(fieldError -> {
222	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
223	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
224	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
225	                        fieldError.getField(),
226	                        defaultMessage,
227	                        rejectedValue);
228	                    return new ValidationMessageDto(message)
229	                        .putAdditionalProperty("field", fieldError.getField())
230	                        .putAdditionalProperty("rejectedValue", rejectedValue)
231	                        .putAdditionalProperty("defaultMessage", defaultMessage);
232	                })
233	                .toList();
234	            logger.debug("Validation error at {} {}: {}",
235	                request.getMethod(),
236	                request.getRequestURI(),
237	                bindingResult.getFieldErrors());
238	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
239	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
240	            return ResponseEntity.status(status).body(detail);
241	        }
242	        return ResponseEntity.status(status).body(detail);
243	    }
244	
245	    /**
246	     * Collects the distinct names of the fields that failed validation, in the order they were
247	     * reported, so responses can list the offending fields (e.g. those that are missing or blank).
248	     *
249	     * @param bindingResult the {@link BindingResult} carrying the validation field errors
250	     * @return the distinct rejected field names
251	     */
252	    private List<String> rejectedFieldNames(BindingResult bindingResult) {
253	        return bindingResult.getFieldErrors().stream()
254	            .map(FieldError::getField)
255	            .distinct()
256	            .toList();
257	    }
258	
259	}
